 second_factor_window_ends_at = CASE WHEN second_factor_window_ends_at <= $2 THEN $3 ELSE second_factor_window_ends_at END
 WHERE id = $1 AND (second_factor_window_ends_at <= $2 OR second_factor_attempts < $4)`,
		id, now, now.Add(store.SecondFactorCooldown), store.MaxSecondFactorAttempts)
	return tag.RowsAffected() == 1, mapErr(err)
}

func (t *tx) BumpAuthzVersions(ctx context.Context, principals []store.Principal) error {
	var users, sas []uuid.UUID
	for _, p := range principals {
		switch p.Type {
		case rbac.PrincipalUser:
			users = append(users, p.ID)
