    48	func (s *Service) CreateMyToken(ctx context.Context, c Caller, req TokenRequest) (CreatedToken, error) {
    49		if err := requireSession(c); err != nil {
    50			return CreatedToken{}, err
    51		}
    52		if err := checkTokenName(req.Name); err != nil {
    53			return CreatedToken{}, err
    54		}
    55		days := s.cfg.DefaultTokenDays
    56		if req.ExpiresInDays != nil {
    57			days = *req.ExpiresInDays
    58			if days < MinTokenDays || days > MaxTokenDays {
    59				return CreatedToken{}, invalid("expires_in_days", "must be between 1 and 3650")
    60			}
    61		}
    62		if req.TOTPCode != nil {
    63			if err := checkTOTPCode("totp_code", *req.TOTPCode); err != nil {
    64				return CreatedToken{}, err
    65			}
    66		}
    67		tok, err := token.New(token.KindUserAPI)
    68		if err != nil {
    69			return CreatedToken{}, internal(err)
    70		}
    71		now := s.clock()
    72		row := store.APIToken{ID: tok.ID, OwnerType: store.OwnerUser, OwnerID: c.ID, Name: req.Name, SecretHash: tok.Hash(), CreatedBy: c.ID, CreatedAt: now}
    73		if !req.NoExpiry {
    74			exp := now.Add(time.Duration(days) * 24 * time.Hour)
    75			row.ExpiresAt = &exp
    76		}
    77		var u store.User
    78		if err := s.inTx(ctx, func(tx store.Tx) error {
    79			var err error
    80			u, err = tx.UserByID(ctx, c.ID)
    81			return err
    82		}); err != nil {
    83			return CreatedToken{}, err
    84		}
    85		reserved := 0
    86		if u.TOTPEnabled {
    87			if req.TOTPCode == nil {
    88				return CreatedToken{}, mfaInvalid()
    89			}
    90			if err := s.inTx(ctx, func(tx store.Tx) error {
    91				var err error
    92				reserved, err = tx.ReserveSessionTOTPAttempt(ctx, *c.SessionID)
    93				return err
    94			}); err != nil {
    95				return CreatedToken{}, err
    96			}
    97			if reserved == 0 {
    98				return CreatedToken{}, &Error{Kind: KindUnauthenticated, Message: "session is no longer valid, log in again"}
    99			}
   100		}
   101		err = s.inTx(ctx, func(tx store.Tx) error {
   102			u, err := tx.LockUser(ctx, c.ID)
   103			if err != nil {
   104				return err
   105			}
   106			if u.TOTPEnabled {
   107				if req.TOTPCode == nil || reserved == 0 {
   108					return mfaInvalid()
   109				}
   110				if err := s.verifyTOTP(ctx, tx, u, *req.TOTPCode, now); err != nil {
   111					return err
   112				}
   113			}
   114			if reserved > 0 {
   115				if err := tx.RefundSessionTOTPAttempt(ctx, *c.SessionID); err != nil {
   116					return err
   117				}
   118			}
   119			return tx.CreateAPIToken(ctx, row)
   120		})
   121		if errors.Is(err, errVerification) {
   122			if reserved >= store.MaxSessionTOTPFailures {
   123				if rerr := s.inTx(ctx, func(tx store.Tx) error { return tx.RevokeSession(ctx, *c.SessionID, s.clock()) }); rerr != nil {
   124					return CreatedToken{}, rerr
   125				}
   126			}
   127			return CreatedToken{}, mfaInvalid()
   128		}
   129		if err != nil {
   130			return CreatedToken{}, err
   131		}
   132		return CreatedToken{APIToken: row, Token: tok.String()}, nil
   133	}
