# In-memory PostgreSQL wire client; disposable-schema concurrency test, no source writes.
import socket, struct, hashlib, hmac, base64, os, uuid, threading, time
class DB:
 def __init__(self):
  self.s=socket.create_connection(('127.0.0.1',15432)); self.s.settimeout(10)
  p=b'user\0postgres\0database\0postgres\0\0'; self.s.sendall(struct.pack('!II',len(p)+8,196608)+p)
  while True:
   t,p=self.msg()
   if t==b'R':
    n=struct.unpack('!I',p[:4])[0]
    if n==3:self.send(b'p',b'audit-only-password\0')
    elif n==10:
     nonce=base64.b64encode(os.urandom(18)).decode(); first='n=postgres,r='+nonce
     text='n,,'+first; self.send(b'p',b'SCRAM-SHA-256\0'+struct.pack('!I',len(text))+text.encode())
    elif n==11:
     server=p[4:].decode(); d=dict(x.split('=',1) for x in server.split(',')); final='c=biws,r='+d['r']
     salt=hashlib.pbkdf2_hmac('sha256',b'audit-only-password',base64.b64decode(d['s']),int(d['i']))
     ck=hmac.digest(salt,b'Client Key','sha256'); sig=hmac.digest(hashlib.sha256(ck).digest(),(first+','+server+','+final).encode(),'sha256')
     self.send(b'p',(final+',p='+base64.b64encode(bytes(a^b for a,b in zip(ck,sig))).decode()).encode())
   elif t==b'E':raise Exception(p)
   elif t==b'Z':break
 def read(self,n):
  p=b''
  while len(p)<n:p+=self.s.recv(n-len(p))
  return p
 def msg(self):
  t=self.read(1); n=struct.unpack('!I',self.read(4))[0]; return t,self.read(n-4)
 def send(self,t,p):self.s.sendall(t+struct.pack('!I',len(p)+4)+p)
 def q(self,q):
  self.send(b'Q',q.encode()+b'\0'); rows=[]; err=None
  while True:
   t,p=self.msg()
   if t==b'D':
    count=struct.unpack('!H',p[:2])[0]; i=2; row=[]
    for _ in range(count):
     n=struct.unpack('!i',p[i:i+4])[0]; i+=4; row.append(None if n<0 else p[i:i+n].decode()); i+=max(n,0)
    rows.append(row)
   elif t==b'E':err=' '.join(x[1:].decode() for x in p.split(b'\0') if x)
   elif t==b'Z':break
  if err:raise Exception(err)
  return rows
 def close(self):self.s.close()
admin=DB(); revoke=DB(); transfer=DB(); grant=DB(); schema='review_lock_'+uuid.uuid4().hex
A='00000000-0000-0000-0000-000000000001'; B='00000000-0000-0000-0000-000000000002'; org=str(uuid.uuid4()); results=[]
try:
 admin.q('CREATE SCHEMA '+schema)
 raw=open('web/iam/migrations/0001_init.sql').read().split('-- +goose Down')[0].replace('iam.',schema+'.')
 admin.q(raw)
 admin.q(f"INSERT INTO {schema}.users(id,username,password_hash) VALUES ('{A}','user-a','hash'),('{B}','user-b','hash'); INSERT INTO {schema}.role_bindings(id,principal_type,principal_id,resource_type,resource_id,org_id,role) VALUES ('{uuid.uuid4()}','user','{B}','org','{org}','{org}','owner')")
 revoke.q('BEGIN; SET LOCAL statement_timeout=5000; SET LOCAL deadlock_timeout=100')
 first=revoke.q(f"SELECT principal_id FROM {schema}.role_bindings WHERE org_id='{org}'")
 assert first==[[B]],first
 revoke.q(f"SELECT id FROM {schema}.users WHERE id='{B}' FOR UPDATE")
 # Joining after revokeOrg's first ListBindings does not need B's row lock.
 grant.q(f"BEGIN; SELECT id FROM {schema}.users WHERE id='{A}' FOR UPDATE; INSERT INTO {schema}.role_bindings(id,principal_type,principal_id,resource_type,resource_id,org_id,role) VALUES ('{uuid.uuid4()}','user','{A}','org','{org}','{org}','reader'); COMMIT")
 second=revoke.q(f"SELECT principal_id FROM {schema}.role_bindings WHERE org_id='{org}' ORDER BY principal_id")
 assert second==[[A],[B]],second
 transfer.q('BEGIN; SET LOCAL statement_timeout=5000; SET LOCAL deadlock_timeout=100')
 transfer.q(f"SELECT id FROM {schema}.users WHERE id='{A}' FOR UPDATE")
 pid=int(transfer.q('SELECT pg_backend_pid()')[0][0])
 def wait_for_b():
  try: transfer.q(f"SELECT id FROM {schema}.users WHERE id='{B}' FOR UPDATE"); results.append('transfer acquired B after other transaction aborted')
  except Exception as e: results.append('transfer: '+str(e))
  finally: transfer.q('ROLLBACK')
 thread=threading.Thread(target=wait_for_b); thread.start()
 for _ in range(100):
  if admin.q(f"SELECT coalesce(wait_event_type='Lock',false) FROM pg_stat_activity WHERE pid={pid}")==[['t']]:break
  time.sleep(.01)
 else:raise Exception('transfer never blocked on B')
 try:revoke.q(f"SELECT id FROM {schema}.users WHERE id='{A}' FOR UPDATE"); results.append('revoke acquired A after other transaction aborted')
 except Exception as e:results.append('revoke: '+str(e))
 revoke.q('ROLLBACK'); thread.join()
 print('revokeOrg first principals:',first,'second principals:',second)
 print('\n'.join(results))
 assert any('40P01' in r for r in results),results
 print('CONFIRMED: revokeOrg incremental lock-set expansion reverses global user lock ordering against TransferOwnership.')
finally:
 for c in [revoke,transfer,grant]:
  try:c.q('ROLLBACK')
  except Exception:pass
  c.close()
 admin.q('DROP SCHEMA '+schema+' CASCADE'); admin.close()
PY

